def oldsource(key, id, ix, locator, finding, version=None, limits=None, method=None):
    a=OLD[id]['market_comparisons'][ix]
    source(key,a['vendor'],a['product'],a['source_title'],a['source_url'],version or a['source_version'],locator,finding,limits or 'Documentation primaire consultée ; aucun choix de produit ni déploiement Beaumanoir déduit.',method or 'Texte de la page primaire ouvert et lu')

